"""Adversarial geographic and 3D journeys; these are role-based checks, not user research."""
import json, pathlib, sys, time, shutil, tempfile
from playwright.sync_api import sync_playwright
site=pathlib.Path(sys.argv[1]).resolve()
network=json.loads((site/'data/network.json').read_text())
decisions=json.loads((site/'data/decisions.json').read_text())['decisions']
proposal=next((d for d in decisions if d['lever']=='right_bus'),{})
pair=(proposal.get('swaps') or [None])[0]
def check(ok,label):
    assert ok,label
    print('PASS twin:',label,flush=True)
ids={s['stop_id'] for s in network['stops']}
check(len(ids)==len(network['stops']),'published stop IDs are unique')
check(all(s in ids for r in network['routes'] for p in r['directions'] for s in p['stops']),'every public route stop resolves to a public coordinate')
check(all(len(p['shape'])>=2 for r in network['routes'] for p in r['directions']),'every published route has a path')
with sync_playwright() as p:
    browser=p.chromium.launch(args=['--use-angle=metal'])
    for width,height,reduced in [(1280,720,False),(390,844,False),(390,844,True)]:
        context=browser.new_context(viewport={'width':width,'height':height},offline=True,reduced_motion='reduce' if reduced else 'no-preference')
        page=context.new_page();errors=[];remote=[]
        page.on('pageerror',lambda e:errors.append(str(e)))
        page.on('request',lambda r:remote.append(r.url) if r.url.startswith(('http:','https:')) else None)
        page.goto(site.as_uri()+'/index.html');page.locator('#guide-explore').click();page.wait_for_function('window.insiyab && insiyab.deck.isInitialized && insiyab.map?.isSourceLoaded("basemap")')
        check(page.locator('#map-credit').is_visible() and 'OpenStreetMap' in page.locator('#map-credit').inner_text(),'judge: public map has visible attribution')
        check(page.wait_for_function("insiyab.geoMode && insiyab.map.isSourceLoaded('basemap') && insiyab.map.areTilesLoaded()"),'judge: offline street tiles load from the bundled archive')
        check(page.evaluate("()=>{const layer=insiyab.deck.props.layers.find(l=>l.id==='buses'),b=layer.props.data[0];return [b.seats-1,b.seats,b.seats+1].map(load=>layer.props.getPolygon({...b,load}).length).join(',')==='16,4,3'}"),'accessibility: room, full and above seats have distinct rendered shapes')
        if page.locator('#play').inner_text()=='Pause':page.locator('#play').click()
        if network.get('source'):
            check(network['source']['credit'] in page.locator('#map-credit').inner_text(),'provenance: exact source credit comes from the bundle')
            check(page.locator('#network-invented').inner_text()==network['source']['invented'],'provenance: invented operations use the supplied qualification')
        route=network['routes'][0]
        page.locator('#public-route').select_option(route['route_id'])
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='routes').props.data.every(r=>r.route_id==="+json.dumps(route['route_id'])+")"),'judge: route selector changes the rendered geography')
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='stop-labels').props.data.length>0"),'judge: selected route shows published stop names')
        spacing_check="()=>{const a=insiyab.deck.props.layers.find(l=>l.id==='stop-labels').props.data.map(s=>s.labelBounds);return a.every((b,i)=>a.every((c,j)=>i===j||b.x+b.width<=c.x||c.x+c.width<=b.x||b.y+b.height<=c.y||c.y+c.height<=b.y))}"
        check(page.evaluate(spacing_check),'judge: visible stop-name bounds do not overlap at this viewport')
        page.evaluate("()=>{const d=insiyab.deck.props.layers.find(l=>l.id==='stop-labels').props.data;window.labelBox=d[1].labelBounds;d[1].labelBounds=d[0].labelBounds}")
        try:assert page.evaluate(spacing_check)
        except AssertionError:print('PASS twin: negative control rejects overlapping stop labels',flush=True)
        else:raise AssertionError('Label-spacing assertion cannot fail')
        page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='stop-labels').props.data[1].labelBounds=labelBox")
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='routes').props.getPath(insiyab.deck.props.layers.find(l=>l.id==='routes').props.data[0])")==route['directions'][0]['shape'],'geographer: actual rendered route coordinates match the bundle')
        zoom=page.evaluate('insiyab.map.getZoom()');page.locator('#zoom-in').click()
        check(page.evaluate('insiyab.map.getZoom()')>zoom,'judge: zoom control changes the camera')
        page.locator('#map-reset').click();page.wait_for_timeout(150)
        click=page.evaluate("()=>{const layer=insiyab.deck.props.layers.find(l=>l.id==='buses'),map=insiyab.map,w=map.getCanvas().clientWidth,h=map.getCanvas().clientHeight;for(const b of layer.props.data){const p=layer.props.getPolygon(b),v=map.project([p.reduce((s,x)=>s+x[0],0)/p.length,p.reduce((s,x)=>s+x[1],0)/p.length]);if(v.x>20&&v.x<w-110&&v.y>80&&v.y<h-80)return {x:v.x,y:v.y};}return null;}")
        if click:
            rect=page.locator('#map').bounding_box();page.mouse.click(rect['x']+click['x'],rect['y']+click['y'])
            check('passengers' in page.locator('#public-selection').inner_text() and 'Clock paused' in page.locator('#public-selection').inner_text(),'judge: clicking a bus opens its passenger/seat reading on the map')
        selected_stops=set(s for d in route['directions'] for s in d['stops'])
        stop=next(s for s in network['stops'] if s['stop_id'] not in selected_stops)
        page.locator('#public-search').fill(stop['name']);page.locator('[data-public-stop]').first.click()
        check('invented, not RTA observations' in page.locator('#public-selection').inner_text(),'judge: a real stop does not turn invented counts into RTA observations')
        check(page.locator('#public-selection').is_visible(),'judge: selected stop has a readable record')
        check(page.locator('#public-route').input_value()=='' and page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='stops').props.data.some(s=>s.stop_id===insiyab.selected)"),'judge: a search outside the focused route clears the filter and draws the chosen stop')
        check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='routes').props.data.length===insiyab.model.paths.length"),'geographer: every supplied directional path is drawn, including return routes')
        chosen=page.evaluate('insiyab.selected')
        page.locator('#stop-forecast').click();page.wait_for_function("insiyab.view==='forecast' && document.querySelector('#forecast-stop')===document.activeElement")
        check(page.locator('#forecast-stop').input_value()==chosen,'judge: map selection opens the exact chosen stop after the lazy forecast load')
        check(page.locator('[data-actual]').inner_text()=='?' if page.locator('[data-actual]').count() else 'No forecast was supplied' in page.locator('#challenge').inner_text(),'judge: selected forecast starts hidden or explicitly unavailable')
        available=page.evaluate("INSIYAB_BUNDLE['forecast/boardings-stop.json'].series[0].id")
        page.locator('[data-view=replay]').click();page.locator('#public-route').select_option(network['routes'][-1]['route_id'])
        page.locator('[data-view=forecast]').click();page.locator('#forecast-stop').select_option(available)
        check(page.evaluate("()=>{const series=INSIYAB_BUNDLE['forecast/boardings-stop.json'].series[+document.querySelector('#forecast-series').value],stop=insiyab.model.stops.get(series.id),p=insiyab.map.project([stop.lon,stop.lat]),canvas=insiyab.map.getCanvas();return insiyab.deck.props.layers.find(l=>l.id==='routes').props.data.every(r=>r.route_id===series.route_id)&&p.x>=0&&p.x<=canvas.clientWidth&&p.y>=0&&p.y<=canvas.clientHeight}"),'judge: a previous route filter cannot hide the selected forecast off-map')
        forecast_match="""()=>{const series=INSIYAB_BUNDLE['forecast/boardings-stop.json'].series[+document.querySelector('#forecast-series').value],rows=series.rows.filter(r=>r.horizon===3600&&r.bin_start>=43200).sort((a,b)=>a.bin_start-b.bin_start),row=rows[+document.querySelector('#forecast-time').value],drawn=insiyab.deck.props.layers.find(l=>l.id==='forecast-halos').props.data;return drawn.length===1&&drawn[0].id===series.id&&drawn[0].route_id===series.route_id&&drawn[0].direction===series.direction&&['origin','bin_start','forecast'].every(k=>drawn[0][k]===row[k]);}"""
        if page.locator('[data-actual]').count():
            check(page.evaluate(forecast_match),'judge: map and evidence use identical stop, direction, origin, bin and forecast')
            page.locator('#forecast-time').select_option(index=1)
            check(page.evaluate(forecast_match),'judge: choosing another quarter-hour updates the actual map layer')
            page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='forecast-halos').props.data[0].forecast+=1")
            try:assert page.evaluate(forecast_match)
            except AssertionError:print('PASS twin: negative control rejects a different map forecast',flush=True)
            else:raise AssertionError('Map/evidence equality check cannot fail')
            page.locator('#reveal').click()
            check(page.evaluate(forecast_match),'judge: reveal restores consistent rendered forecast data')
            check(page.evaluate("()=>{const a=insiyab.deck.props.layers.find(l=>l.id==='actual-halos').props.data;return a.length===1&&String(a[0].actual)===document.querySelector('[data-actual]').textContent}"),'judge: map reveals exactly the selected actual')
            page.locator('#reveal').click()
            check(page.evaluate("insiyab.deck.props.layers.find(l=>l.id==='actual-halos').props.data.length===0"),'judge: hiding actual removes it from the map too')
        page.locator('[data-view=replay]').click()
        page.locator('#public-search').fill('zzzz-no-such-stop');check('No published stop matches' in page.locator('#public-search-results').inner_text(),'judge: unknown stop has an explicit empty state')
        page.locator('#public-search').fill('')
        page.locator('#briefing-panel').evaluate('(e)=>e.open=true')
        check(page.locator('#briefing .briefing-facts li').count()>=2 and page.locator('#briefing [data-go]').count()==3,'judge: plain-language briefing gives bundle counts and three ways on')
        check('How many passengers will board?' in page.locator('#briefing').inner_text() and 'How many will be waiting?' not in page.locator('#briefing').inner_text(),'judge: boarding forecasts never claim to measure the waiting queue')
        check(page.get_by_role('region',name='Bus network replay. Choose a bus or stop below for the same information.').get_by_role('button',name='Zoom in',exact=True).count()==1,'accessibility: interactive map controls are inside a named region')
        check('invented service records' in page.locator('#briefing').inner_text() and 'does not prove' in page.locator('#briefing').inner_text(),'judge: briefing distinguishes invented counts and missing waiting evidence')
        check(page.evaluate('document.documentElement.scrollWidth<=innerWidth'),'briefing: no horizontal overflow')
        page.locator('#briefing [data-go="replay"]').click();page.wait_for_timeout(700)
        page.locator('#briefing .briefing-moves a').first.click()
        check(page.evaluate("insiyab.view==='gap'") and page.locator('#decisions .decision').count()>0,'judge: briefing proposal opens the supplied decision evidence')
        page.locator('[data-view=replay]').click()
        page.locator('#briefing-panel').evaluate('(e)=>e.open=false')
        if pair:
            for i,candidate in enumerate(proposal['swaps']):
                page.locator('#swap-pair').select_option(str(i))
                check(page.locator('.swap-trip strong').all_text_contents()==[str(candidate[k]['largest_load'])+' peak passengers' for k in ['from','to']],f'planner: pair {i+1} displays its own peak loads')
                check(page.locator('.swap-capacity>span').all_text_contents()==[f"{candidate[k]['seats']} seats" for k in ['from','to']],f'planner: pair {i+1} starts with original capacities')
                page.locator('#compare-swap').click()
                check(page.locator('.swap-capacity>span').all_text_contents()==[f"{candidate[k]['seats']} seats" for k in ['to','from']],f'planner: pair {i+1} swaps only the supplied capacities')
                if i in [0,len(proposal['swaps'])-1]:
                    for side in ['from','to']:
                        page.locator(f'[data-swap-side="{side}"]').click()
                        check(page.evaluate('insiyab.selected')==candidate[side]['trip_id'],'planner: trip action selects the exact replay trip')
                        actual=page.evaluate("insiyab.buses.find(b=>b.trip_id===insiyab.selected)")
                        check(actual['load']==candidate[side]['largest_load'] and actual['seats']==candidate[side]['seats'],'planner: map shows the original peak record while the proposal stays simulated')
                        check('Original replay' in page.locator('#public-selection').inner_text(),'judge: comparison never relabels original replay as simulated')
                if i:check(page.locator('#meet-worker').count()==0,'judge: a different pair does not imply it belongs to the supplied worker story')
            page.locator('#swap-pair').select_option('0')
            before=page.locator('.swap-capacity>span').all_text_contents()
            check(before==[f"{pair['from']['seats']} seats",f"{pair['to']['seats']} seats"],'planner: current capacities match the exact proposed pair')
            page.locator('#compare-swap').focus();start=time.monotonic();page.locator('#compare-swap').press('Enter')
            check(time.monotonic()-start<2,'judge: swap responds within two seconds')
            check(page.evaluate("document.activeElement.id==='compare-swap'"),'keyboard: comparison retains focus after replacing its content')
            check('Simulated exchange' in page.locator('#executive-status').inner_text(),'screen reader: comparison announces the changed result')
            check(page.locator('.swap-capacity>span').all_text_contents()==before[::-1],'planner: exchange changes each trip to the other supplied capacity')
            check('simulated' in page.locator('.executive-state').inner_text(),'planner: changed capacities are visibly simulated')
            check(str(pair['empty_km']) in page.locator('.swap-constraint').inner_text(),'planner: empty-running tradeoff stays beside the action')
            page.locator('#executive details summary').click();check('not checked' in page.locator('#executive details').inner_text().lower(),'planner: unchecked operational constraints are exposed')
            check('full proposal:' in page.locator('#executive details').inner_text() and 'this pair only' in page.locator('#executive details').inner_text(),'planner: programme-wide costs are distinguished from the selected pair')
            page.locator('#meet-worker').click()
        else:
            check('No paired vehicle exchange' in page.locator('#executive').inner_text(),'planner: no feasible exchange is explicit')
            page.locator('[data-view=stories]').click();page.locator('[data-person=\"1\"]').click();page.locator('#story-next').click()
        check(page.evaluate("insiyabScene.role==='site_worker' && insiyabScene.kind==='simulated'"),'site worker: decision opens the matching changed perspective')
        page.wait_for_timeout(1650 if not reduced else 50)
        frames=page.evaluate('insiyabScene.frames');page.wait_for_timeout(120)
        check(page.evaluate('insiyabScene.frames')==frames,'accessibility: transition stops rendering after its final state')
        if reduced:check(page.evaluate('insiyabScene.moving.every(x=>x===-1)'),'accessibility: reduced motion immediately reaches the arrival state')
        old=page.evaluate('insiyabScene.camera.position.toArray()');pixels=page.locator('#scene canvas').screenshot()
        page.locator('[data-camera]').click()
        check(page.evaluate('insiyabScene.camera.position.toArray()')!=old and page.locator('#scene canvas').screenshot()!=pixels,'site worker: seat-view control changes the real camera and pixels')
        page.evaluate('window.firstTwinRenderer=insiyabScene.renderer')
        page.locator('[data-person="1"]').click()
        placement="()=>{const people=insiyabScene.scene.getObjectsByProperty('name','passenger-above-seats');return new Set(people.map(p=>p.position.toArray().join(','))).size===people.length}"
        check(page.evaluate(placement),'site worker: every passenger above seats occupies a distinct position')
        check(page.evaluate("()=>{const boxes=insiyabScene.standingBounds;return boxes.every((a,i)=>boxes.every((b,j)=>i===j||a.min.some((v,k)=>v>=b.max[k]||a.max[k]<=b.min[k])))}"),'site worker: actual standing-figure bounds do not intersect')
        if page.evaluate("insiyabScene.scene.getObjectsByProperty('name','passenger-above-seats').length>=2"):
            page.evaluate("()=>{const p=insiyabScene.scene.getObjectsByProperty('name','passenger-above-seats');window.originalPosition=p[1].position.clone();p[1].position.copy(p[0].position)}")
            try:assert page.evaluate(placement)
            except AssertionError:print('PASS twin: negative control catches overlapping standing figures',flush=True)
            else:raise AssertionError('Standing-position check cannot fail')
            page.evaluate("insiyabScene.scene.getObjectsByProperty('name','passenger-above-seats')[1].position.copy(originalPosition)")
        for i in range(16):page.locator(f'[data-person="{i%4}"]').click()
        check(page.evaluate('insiyabScene.renderer===firstTwinRenderer'),'graphics: repeated role changes reuse one WebGL context')
        page.locator('[data-person="3"]').click();page.locator('#story-next').click()
        check('do not establish' in page.locator('#scene-caption').inner_text(),'driver: closed doors are not evidence of an empty stop')
        check(page.locator('#story-assumption').is_visible() and 'cannot tell us who was waiting' in page.locator('#story-assumption').inner_text(),'driver: request assumption is beside the finding, not hidden below the scene')
        page.locator('[data-replay]').click();check('illustration only' in page.locator('.scene-reading').inner_text(),'driver: stop-request interaction remains explicitly illustrative')
        page.locator('[data-person="2"]').click();page.locator('#story-next').click()
        check(page.locator('#story-action a').get_attribute('href')=='khutwa/','office worker: the offer goes to the existing passenger flow')
        check(page.evaluate('document.documentElement.scrollWidth<=innerWidth'),'accessibility: no horizontal overflow after every role')
        check(not errors,f'no unhandled errors: {errors}')
        check(not remote,f'network disabled throughout: {remote}')
        context.close()
    with tempfile.TemporaryDirectory(prefix='insiyab-map-failure-') as tmp:
        failed=pathlib.Path(tmp);shutil.copytree(site,failed,dirs_exist_ok=True);(failed/'map/offline.js').unlink()
        context=browser.new_context(offline=True,viewport={'width':390,'height':844});page=context.new_page();errors=[]
        page.on('pageerror',lambda e:errors.append(str(e)))
        page.goto(failed.as_uri()+'/index.html');page.locator('#guide-explore').click();page.wait_for_function('window.insiyab && insiyab.deck.isInitialized')
        check(page.evaluate('!insiyab.geoMode'),'failure control: missing offline map selects the network-only renderer')
        check(page.evaluate("()=>{const layer=insiyab.deck.props.layers.find(l=>l.id==='buses'),b=layer.props.data[0];return [b.seats-1,b.seats,b.seats+1].map(load=>layer.props.getPolygon({...b,load}).length).join(',')==='16,4,3'}"),'fallback: room, full and above seats match the same legend')
        check('network is drawn alone' in page.locator('#map-tile-note').inner_text(),'fallback: missing streets are disclosed')
        note=page.locator('#map-tile-note').bounding_box();credit=page.locator('#map-credit').bounding_box()
        check(note['y']+note['height']<=credit['y'],'fallback: missing-map notice does not cover source attribution')
        page.locator('#record-inspector').evaluate('(e)=>e.open=true');page.locator('#entity-type').select_option('bus')
        check('seats' in page.locator('#detail').inner_text(),'fallback: supplied records remain usable')
        check(not errors,f'fallback: failure causes no unhandled error: {errors}')
        context.close()
    browser.close()
print('TWIN REVIEW PASS')
